final_template:
AWSTemplateFormatVersion: '2010-09-09'

Description: >-
  IoT device-onboarding policy stack. Provisions a Lambda-backed CloudFormation
  custom resource that generates an AWS IoT Core policy scoped to each device's
  own thing name (connect, publish, subscribe, receive), and outputs the
  generated policy name. Self-contained: no external VPCs, secrets, SSM
  parameters, or cross-stack imports are referenced.

Parameters:

  PolicyNamePrefix:
    Type: String
    Default: device-onboarding
    Description: >-
      Prefix for the generated IoT policy name. Only letters, digits,
      underscores and hyphens are permitted.
    AllowedPattern: '[a-zA-Z0-9_-]+'
    ConstraintDescription: Must contain only letters, digits, underscores or hyphens.
    MinLength: 1
    MaxLength: 64

  EnvironmentTag:
    Type: String
    Default: dev
    Description: Value applied as the Environment tag on the Lambda function and IAM role.
    AllowedPattern: '[a-zA-Z0-9_-]+'
    ConstraintDescription: Must contain only letters, digits, underscores or hyphens.
    MinLength: 1
    MaxLength: 32

Resources:

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role for the IoT device-onboarding policy custom resource Lambda.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IoTDeviceOnboardingPolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: ManageOnboardingPolicies
                Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicyVersion
                  - iot:ListPolicyVersions
                  - iot:ListTargetsForPolicy
                Resource: !Sub 'arn:${AWS::Partition}:iot:${AWS::Region}:${AWS::AccountId}:policy/${PolicyNamePrefix}-*'
      Tags:
        - Key: Environment
          Value: !Ref EnvironmentTag
        - Key: ManagedBy
          Value: !Ref 'AWS::StackName'

  OnboardingPolicyFunctionLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub '/aws/lambda/${AWS::StackName}-iot-onboarding-policy'
      RetentionInDays: 14
      Tags:
        - Key: Environment
          Value: !Ref EnvironmentTag
        - Key: ManagedBy
          Value: !Ref 'AWS::StackName'

  OnboardingPolicyFunction:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: !Sub '${AWS::StackName}-iot-onboarding-policy'
      Description: Creates, versions and deletes the IoT device-onboarding policy for this stack.
      Handler: index.handler
      Runtime: nodejs22.x
      Role: !GetAtt LambdaExecutionRole.Arn
      Timeout: 60
      MemorySize: 256
      Environment:
        Variables:
          POLICY_NAME_PREFIX: !Ref PolicyNamePrefix
          ENVIRONMENT_TAG: !Ref EnvironmentTag
          STACK_NAME: !Ref 'AWS::StackName'
          IOT_PARTITION: !Ref 'AWS::Partition'
          IOT_REGION: !Ref 'AWS::Region'
          IOT_ACCOUNT_ID: !Ref 'AWS::AccountId'
      Code:
        ZipFile: |
          const https = require('https');
          const { IoTClient, CreatePolicyCommand, CreatePolicyVersionCommand,
            DeletePolicyCommand, DeletePolicyVersionCommand,
            ListPolicyVersionsCommand } = require('@aws-sdk/client-iot');

          const iot = new IoTClient({});
          const E = process.env;

          function send(event, context, status, data, pid, reason) {
            const body = JSON.stringify({
              Status: status,
              Reason: reason || ('See CloudWatch log stream ' + context.logStreamName),
              PhysicalResourceId: pid || context.logStreamName,
              StackId: event.StackId,
              RequestId: event.RequestId,
              LogicalResourceId: event.LogicalResourceId,
              NoEcho: false,
              Data: data || {}
            });
            const u = new URL(event.ResponseURL);
            return new Promise((resolve) => {
              const req = https.request({
                hostname: u.hostname, port: 443,
                path: u.pathname + u.search, method: 'PUT',
                headers: { 'content-type': '', 'content-length': Buffer.byteLength(body) }
              }, (res) => { res.resume(); res.on('end', resolve); });
              req.on('error', (e) => { console.error('send failed', e); resolve(); });
              req.write(body);
              req.end();
            });
          }

          function policyDocument() {
            const t = '${iot:Connection.Thing.ThingName}';
            const b = 'arn:' + E.IOT_PARTITION + ':iot:' + E.IOT_REGION + ':' + E.IOT_ACCOUNT_ID + ':';
            return JSON.stringify({
              Version: '2012-10-17',
              Statement: [
                { Sid: 'ConnectAsOwnThing', Effect: 'Allow', Action: 'iot:Connect',
                  Resource: b + 'client/' + t },
                { Sid: 'PublishOwnTopics', Effect: 'Allow', Action: 'iot:Publish',
                  Resource: [b + 'topic/devices/' + t + '/*',
                             b + 'topic/$aws/things/' + t + '/shadow/*'] },
                { Sid: 'SubscribeOwnTopics', Effect: 'Allow', Action: 'iot:Subscribe',
                  Resource: [b + 'topicfilter/devices/' + t + '/*',
                             b + 'topicfilter/$aws/things/' + t + '/shadow/*'] },
                { Sid: 'ReceiveOwnTopics', Effect: 'Allow', Action: 'iot:Receive',
                  Resource: [b + 'topic/devices/' + t + '/*',
                             b + 'topic/$aws/things/' + t + '/shadow/*'] }
              ]
            });
          }

          const suffix = (id) => String(id || '').replace(/[^a-zA-Z0-9]/g, '').slice(0, 8).toLowerCase();
          const build = (prefix, reqId) => prefix + '-' + E.STACK_NAME + '-' + suffix(reqId);
          const owned = (name) => typeof name === 'string' &&
            name.startsWith(E.POLICY_NAME_PREFIX + '-') === false ? false : true;

          async function createPolicy(name) {
            await iot.send(new CreatePolicyCommand({
              policyName: name, policyDocument: policyDocument()
            }));
          }

          async function pruneVersions(name, keepDefault) {
            const out = await iot.send(new ListPolicyVersionsCommand({ policyName: name }));
            const versions = out.policyVersions || [];
            for (const v of versions) {
              if (v.isDefaultVersion && keepDefault) continue;
              if (v.isDefaultVersion && !keepDefault) continue;
              await iot.send(new DeletePolicyVersionCommand({
                policyName: name, policyVersionId: v.versionId
              }));
            }
          }

          async function deletePolicy(name) {
            try {
              await pruneVersions(name, false);
              await iot.send(new DeletePolicyCommand({ policyName: name }));
            } catch (err) {
              if (err.name === 'ResourceNotFoundException') return;
              throw err;
            }
          }

          exports.handler = async (event, context) => {
            console.log('event', JSON.stringify(event));
            const props = event.ResourceProperties || {};
            const oldProps = event.OldResourceProperties || {};
            const prefix = props.PolicyNamePrefix || E.POLICY_NAME_PREFIX;
            let pid = event.PhysicalResourceId;
            try {
              if (event.RequestType === 'Create') {
                const name = build(prefix, event.RequestId);
                await createPolicy(name);
                return await send(event, context, 'SUCCESS', { PolicyName: name }, name);
              }
              if (event.RequestType === 'Update') {
                const prevPrefix = oldProps.PolicyNamePrefix || E.POLICY_NAME_PREFIX;
                if (prevPrefix !== prefix || !owned(pid)) {
                  const name = build(prefix, event.RequestId);
                  await createPolicy(name);
                  return await send(event, context, 'SUCCESS', { PolicyName: name }, name);
                }
                await pruneVersions(pid, true);
                await iot.send(new CreatePolicyVersionCommand({
                  policyName: pid, policyDocument: policyDocument(), setAsDefault: true
                }));
                return await send(event, context, 'SUCCESS', { PolicyName: pid }, pid);
              }
              if (event.RequestType === 'Delete') {
                if (owned(pid) && pid !== context.logStreamName) await deletePolicy(pid);
                return await send(event, context, 'SUCCESS', { PolicyName: pid }, pid);
              }
              return await send(event, context, 'FAILED', {}, pid,
                'Unsupported RequestType ' + event.RequestType);
            } catch (err) {
              console.error('handler failed', err);
              return await send(event, context, 'FAILED', {}, pid,
                (err && err.message) ? err.message : String(err));
            }
          };
      Tags:
        - Key: Environment
          Value: !Ref EnvironmentTag
        - Key: ManagedBy
          Value: !Ref 'AWS::StackName'

  IoTDevicePolicy:
    Type: Custom::IoTDevicePolicy
    DependsOn: OnboardingPolicyFunctionLogGroup
    Properties:
      ServiceToken: !GetAtt OnboardingPolicyFunction.Arn
      PolicyNamePrefix: !Ref PolicyNamePrefix
      EnvironmentTag: !Ref EnvironmentTag

Outputs:

  IoTDevicePolicyName:
    Description: Name of the generated IoT Core device-onboarding policy, scoped to each device's own thing name.
    Value: !GetAtt IoTDevicePolicy.PolicyName
    Export:
      Name: !Sub '${AWS::StackName}-IoTDevicePolicyName'

  OnboardingPolicyFunctionArn:
    Description: ARN of the Lambda function backing the IoT device-onboarding policy custom resource.
    Value: !GetAtt OnboardingPolicyFunction.Arn
    Export:
      Name: !Sub '${AWS::StackName}-OnboardingPolicyFunctionArn'
